#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 4;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Shared memory: weights for OcPerBlock output channels
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  const int per_oc_wsize = Cin * Kh * Kw;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, Cin, Kh, Kw),
      make_stride(per_oc_wsize, Kh * Kw, Kw, Int<1>{})
  );

  const int wsize = OcPerBlock * per_oc_wsize;
  for (int idx = tid; idx < wsize; idx += Threads) {
    int occ = idx / per_oc_wsize;
    int rem = idx - occ * per_oc_wsize;
    int oc = oc_base + occ;
    T val = T(0);
    if (oc < Cout) {
      val = W[(int64_t)oc * per_oc_wsize + rem];
    }
    sW_ptr[idx] = val;
  }
  __syncthreads();

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  for (int ic = 0; ic < Cin; ++ic) {
    for (int kh = 0; kh < Kh; ++kh) {
      int ih_arr[PVec];
      bool hv_arr[PVec];
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) { hv_arr[i] = false; ih_arr[i] = 0; continue; }
        int ih = oh_arr[i] * stride_h - pad_h + kh * dil_h;
        hv_arr[i] = ((unsigned)ih < (unsigned)H);
        ih_arr[i] = ih;
      }

      for (int kw = 0; kw < Kw; ++kw) {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!hv_arr[i]) continue;
          int p = p_idx[i];
          if (p >= P_total) continue;

          int iw = ow_arr[i] * stride_w - pad_w + kw * dil_w;
          if ((unsigned)iw >= (unsigned)Win) continue;

          float xval = (float)mX(ic, ih_arr[i], iw);

          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            int oc = oc_base + occ;
            if (oc >= Cout) continue;
            float wval = (float)sW(occ, ic, kh, kw);
            acc[occ][i] += xval * wval;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t Kh   = w.size(2);
  int64_t Kw   = w.size(3);

  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 4;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)OcPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input and asymmetric kernel,
    dilation and padding, implemented with a single custom CUDA kernel
    using CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(kernel_size[0]), int(kernel_size[1]))

        if isinstance(stride, (tuple, list)):
            self.stride = (int(stride[0]), int(stride[1]))
        else:
            self.stride = (int(stride), int(stride))

        self.padding = (int(padding[0]), int(padding[1]))
        self.dilation = (int(dilation[0]), int(dilation[1]))

        Kh, Kw = self.kernel_size
        Cin = self.in_channels
        Cout = self.out_channels

        self.weight = nn.Parameter(torch.empty(Cout, Cin, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride[0]), int(self.stride[1]),
            int(self.padding[0]), int(self.padding[1]),
            int(self.dilation[0]), int(self.dilation[1]),
        )

